def evaluate_mechanism(length: int, density: int, stride_val: int, tid: str = '') -> int:
    return (
        (0 if (((stride_val * -2 + density * -2) % 3) == 0) else 1)
        if (tid == 'task_j1_multiscale_run_parity')
        else (0 if ((density % 2 == 0) and (length >= 3)) else 1)
        if (tid == 'task_j2_symmetric_run_boundary')
        else (0 if (((length * -1) % 3) == 0) else 1)
        if (tid == 'task_k1_center_pivot_density')
        else (0 if (((stride_val * -2 + density * -2) % 3) == 0) else 1)
        if (tid == 'task_k2_modular_stride_shift')
        else (0 if ((length % 3) == 0) else 1)
    )
